# 2019_phone.dta -- Canadian Election Study, 13 demographic variables
survey(
  survey_id = "2019_phone.dta",
  source    = "Canadian Election Study",
  file_name = "2019 Canadian Election Study - Phone Survey v1.1.dta",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- age | age -- Age (based on year of birth, Q2)
      age = in_range(..d[["age"]], 18, 100),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- q61 | q61 -- What is the highest level of education that you have completed?
      degree = recode_values(as.numeric(..d[["q61"]]), 1:8 ~ 0, 9:11 ~ 1),
      # gender <- q3 | q3 -- Gender
      gender = recode_values(as.numeric(..d[["q3"]]), 1 ~ 0, 2 ~ 1, 3 ~ 2),
      # mother_tongue <- q67 | q67 -- What is the first language you learned and still understand?
      mother_tongue = recode_values(as.numeric(..d[["q67"]]), -8 ~ 98, 1 ~ 2, 2:3 ~ 4, 4 ~ 1, 5:8 ~ 4, 10:14 ~ 4, 17:20 ~ 4, 22:31 ~ 4),
      # province <- q4 | q4 -- In which province or territory are you currently living?
      province = recode_values(as.numeric(..d[["q4"]]), 1 ~ 10, 2 ~ 11, 3 ~ 12, 4 ~ 13, 5 ~ 24, 6 ~ 35, 7 ~ 46, 8 ~ 47, 9 ~ 48, 10 ~ 59),
      # region <- q4 | q4 -- In which province or territory are you currently living?
      region = recode_values(as.numeric(..d[["q4"]]), 1:4 ~ 1, 5 ~ 2, 6 ~ 3, 7:9 ~ 4, 10 ~ 5),
      # religion <- q62 | q62 -- Please tell me what is your religion, if you have one?
      religion = recode_values(as.numeric(..d[["q62"]]), -9 ~ 5, 1 ~ 2, 2 ~ 4, 3:4 ~ 2, 5 ~ 4, 6 ~ 1, 7 ~ 2, 8 ~ 4, 9 ~ 2, 10:11 ~ 4, 12 ~ 2, 13 ~ 4, 14 ~ 2, 15 ~ 3, 16:18 ~ 2, 19 ~ 4, 20 ~ 2, 21 ~ 5, 22 ~ 4),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(3, nrow(..d)),
      # vote_choice <- p3 | p3 -- Which party did you vote for?
      vote_choice = recode_values(as.numeric(..d[["p3"]]), -9 ~ 99, -8 ~ 98, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 6, 5 ~ 10, 6:7 ~ 9, 8 ~ 98),
      # vote_intention <- vote | vote -- (combined Q10, Q11, Q12) Party respondent will/might/has vote(d) for
      vote_intention = recode_values(as.numeric(..d[["vote"]]), -8 ~ 98, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 6, 5 ~ 10, 6:7 ~ 9, 8 ~ 98, 9 ~ 9, 10 ~ 95, 11 ~ 99),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  }
)

