# cdem2023.dta -- Canadian Election Study, 12 demographic variables
survey(
  survey_id = "cdem2023.dta",
  source    = "Canadian Election Study",
  file_name = "2023 Democracy Checkup Dataset v1.dta",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- dc23_age_in_years | To make sure we are talking to a cross section of   Canadians, we need to get a
      age = in_range(as.numeric(..d[["dc23_age_in_years"]]) + 0, 18, 93),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- dc23_education | What is the highest level of education that you have completed?
      degree = recode_values(as.numeric(..d[["dc23_education"]]), 1:8 ~ 0, 9:11 ~ 1),
      # gender <- dc23_genderid | Are you...? - Selected Choice
      gender = recode_values(as.numeric(..d[["dc23_genderid"]]), 1 ~ 0, 2 ~ 1, 3:4 ~ 2),
      # mother_tongue <- dc23_language_1..dc23_language_3 | Which language(s) did you learn as a child and still understand today?
      mother_tongue = case_when((sel(..d[["dc23_language_3"]])) ~ 4, sel(..d[["dc23_language_1"]]) & sel(..d[["dc23_language_2"]]) ~ 3, sel(..d[["dc23_language_1"]]) ~ 2, sel(..d[["dc23_language_2"]]) ~ 1, TRUE ~ NA_real_),
      # province <- dc23_province | Which province or territory are you currently living in?
      province = recode_values(as.numeric(..d[["dc23_province"]]), 1 ~ 48, 2 ~ 59, 3 ~ 46, 4 ~ 13, 5 ~ 10, 7 ~ 12, 9 ~ 35, 10 ~ 11, 11 ~ 24, 12 ~ 47),
      # region <- dc23_province | Which province or territory are you currently living in?
      region = recode_values(as.numeric(..d[["dc23_province"]]), 1 ~ 4, 2 ~ 5, 3 ~ 4, 4:5 ~ 1, 7 ~ 1, 9 ~ 3, 10 ~ 1, 11 ~ 2, 12 ~ 4),
      # religion <- dc23_religion | Please tell me what is your religion, if you have one? - Selected Choice
      religion = recode_values(as.numeric(..d[["dc23_religion"]]), 1:2 ~ 5, 3:7 ~ 4, 8:9 ~ 2, 10 ~ 1, 11:12 ~ 4, 13 ~ 2, 14 ~ 4, 15:21 ~ 2, 22 ~ 4),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(2, nrow(..d)),
      # vote_intention <- dc23_vote_choice | If a federal election were held today, which party would you be most likely to v
      vote_intention = recode_values(as.numeric(..d[["dc23_vote_choice"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 6, 5 ~ 10, 6 ~ 9, 7 ~ 97, 8 ~ 98, 9 ~ 10),
      # language <- mother_tongue | mother tongue (no language-at-home question in this survey)
      language = in_range(mother_tongue, 1, 99),
      # language_var <- mother_tongue | which source supplied language: 2 = mother tongue
      language_var = recode_values(as.numeric(mother_tongue), 1:99 ~ 2)
    )
  }
)

