# 1974.dta -- Canadian Election Study, 16 demographic variables, 2 issue questions
survey(
  survey_id = "1974.dta",
  source    = "Canadian Election Study",
  file_name = "CES-E-1974-1980_F1_1974wave.dta",
  file_id   = "1974-1980.dta",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- v477 | RESPONDENT AGE IN YEARS
      age = in_range(..d[["v477"]], 18, 88),
      # age_cats <- v477 | RESPONDENT AGE IN YEARS
      age_cats = recode_values(as.numeric(..d[["v477"]]), 18:29 ~ 1, 30:49 ~ 2, 50:86 ~ 3, 88 ~ 3),
      # com_100 <- v480 then v1536 | COMMUNITY SIZE
      com_100 = split_on(..d[["v480"]], recode_values(as.numeric(..d[["v480"]]), 1:4 ~ 1, 5:9 ~ 0), c(0), recode_values(as.numeric(..d[["v1536"]]), 1:4 ~ 1, 5:9 ~ 0)),
      # com_500 <- v480 | COMMUNITY SIZE
      com_500 = recode_values(as.numeric(..d[["v480"]]), 0 ~ 0, 1 ~ 1, 2 ~ 0, 3 ~ 1, 4:9 ~ 0),
      # degree <- v444 x v446 | base from v444; v446==1 sets 1 (from ces_recodes.R)
      degree = pair_recode(..d[["v444"]], ..d[["v446"]], c("1|1" = 1, "1|2" = 0, "1|NA" = 0, "2|1" = 1, "2|2" = 0, "2|NA" = 0, "8|NA" = 0, "NA|1" = 1)),
      # gender <- v2156 or v1537 | SEX OF RESPONDENT
      gender = coalesce(recode_values(as.numeric(..d[["v2156"]]), 1 ~ 0, 2 ~ 1), recode_values(as.numeric(..d[["v1537"]]), 1 ~ 0, 2 ~ 1)),
      # language_home <- v1510 | LANGUAGE SPOKEN AT HOME
      language_home = recode_values(as.numeric(..d[["v1510"]]), 1 ~ 2, 2 ~ 1, 3 ~ 3, 4:7 ~ 4),
      # mother_tongue <- v470 | LANGUAGE SPOKEN AS CHILD
