      gender = recode_values(as.numeric(..d[["var456"]]), 1 ~ 0, 2 ~ 1),
      # language_home <- var375 | q.l-10b language speak at home
      language_home = recode_values(as.numeric(..d[["var375"]]), 1 ~ 2, 2 ~ 1, 3 ~ 3, 4:7 ~ 4),
      # mother_tongue <- var374 | q.l-10a r mother-tongue
      mother_tongue = recode_values(as.numeric(..d[["var374"]]), 1 ~ 2, 2 ~ 1, 3:29 ~ 4, 30 ~ 3, 31:33 ~ 4),
