      occupation = recode_values(as.numeric(..d[["var525"]]), 1 ~ 2, 2 ~ 1, 3:4 ~ 3, 5:6 ~ 4, 7 ~ 6, 8 ~ 99),
      # province <- var463 | info: province
      province = recode_values(as.numeric(..d[["var463"]]), 0 ~ 10, 1 ~ 11, 2 ~ 12, 3 ~ 13, 4 ~ 24, 5 ~ 35, 6 ~ 46, 7 ~ 47, 8 ~ 48, 9 ~ 59),
      # region <- var003 | screener: region of interview
      region = recode_values(as.numeric(..d[["var003"]]), 0:3 ~ 1, 4 ~ 2, 5 ~ 3, 6:8 ~ 4, 9 ~ 5),
      # religion <- var371 | q.l-9a r religious affiliation
      religion = recode_values(as.numeric(..d[["var371"]]), 0 ~ 5, 1 ~ 1, 2:6 ~ 2, 7 ~ 1, 8 ~ 4, 9 ~ 3, 10:11 ~ 2, 12 ~ 4, 13:16 ~ 2, 17 ~ 4, 18:20 ~ 2, 28:29 ~ 2, 30:33 ~ 4, 34 ~ 5, 35 ~ 99),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(1, nrow(..d)),
      # vote_choice <- var125 | q.e-1b which party did r vote
      vote_choice = recode_values(as.numeric(..d[["var125"]]), 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 4, 5 ~ 9, 8 ~ 9, 9 ~ 10, 10 ~ 9, 12 ~ 9, 13 ~ 95, 15:16 ~ 9, 20 ~ 96),
      # vote_intention <- var268 | q.g-7a party r would vote now fed. elec.
