      # vote_choice <- xb2 | party voted for in this election
      vote_choice = recode_values(as.numeric(..d[["xb2"]]), 1 ~ 2, 2 ~ 1, 3 ~ 3, 4 ~ 8, 5 ~ 9, 8 ~ 99, 9 ~ 98),
