      ces_idim_004 = recode_values(cpsf1a, 0 ~ 9999, c(1, 2) ~ 1, 3 ~ 0, c(4, 5) ~ -1, 8 ~ 9999, 9 ~ NA_real_),

      # Aboriginals could be well off if tried
      # mbse9
