# 2000.dta -- Canadian Election Study, 14 demographic variables, 76 issue questions
survey(
  survey_id = "2000.dta",
  source    = "Canadian Election Study",
  file_name = "ces2000.dta",
  demographics = function(..d) {
    ..d %>% transmute(
      # age <- cpsage | to make sure we are talking to a cross section of canadians, we need to get a li
      age = in_range(2000 - as.numeric(..d[["cpsage"]]), 18, 98),
      # age_cats <- age | constructed from continuous age
      age_cats = recode_values(as.numeric(age), 0:29 ~ 1, 30:49 ~ 2, 50:125 ~ 3),
      # degree <- cpsm3 | what is the highest level of education that you have completed?
      degree = recode_values(as.numeric(..d[["cpsm3"]]), 1:8 ~ 0, 9:11 ~ 1),
      # gender <- cpsrgen | respondent's gender
      gender = recode_values(as.numeric(..d[["cpsrgen"]]), 1 ~ 0, 5 ~ 1),
      # language_home <- cpsm14 | what language do you usually speak at home?
      language_home = recode_values(as.numeric(..d[["cpsm14"]]), 0 ~ 4, 1 ~ 2, 5 ~ 1, 98 ~ 99, 99 ~ 98),
      # mother_tongue <- cpsm15 | what is the first language you learned and still understand?
      mother_tongue = recode_values(as.numeric(..d[["cpsm15"]]), 0 ~ 4, 1 ~ 2, 5 ~ 1, 98 ~ 99, 99 ~ 98),
      # province <- province | province of interview
      province = in_range(..d[["province"]], 10, 59),
      # region <- province | province of interview
      region = recode_values(as.numeric(..d[["province"]]), 10:13 ~ 1, 24 ~ 2, 35 ~ 3, 46:48 ~ 4, 59 ~ 5),
      # religion <- cpsm10 | what is your religious affiliation?  is it protestant, catholic, jewish, islam,
      religion = recode_values(as.numeric(..d[["cpsm10"]]), 0 ~ 5, 1 ~ 2, 2 ~ 1, 3 ~ 3, 4:5 ~ 4, 9 ~ 4, 98 ~ 99, 99 ~ 97),
      # survey_mode <- assigned by hand | assigned by hand; not in the survey file
      survey_mode = rep(3, nrow(..d)),
      # vote_choice <- pesa3b or pesa3a | which party did you vote for: the liberal party, the alliance party, the conserv
      vote_choice = coalesce(recode_values(as.numeric(..d[["pesa3b"]]), 0 ~ 9, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 97 ~ 96, 98 ~ 99, 99 ~ 98), recode_values(as.numeric(..d[["pesa3a"]]), 0 ~ 9, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 8, 5 ~ 6, 97 ~ 96, 98 ~ 99, 99 ~ 98)),
      # vote_intention <- cpsa4 | which party do you think you will vote for: the liberal party, the alliance part
      vote_intention = recode_values(as.numeric(..d[["cpsa4"]]), 0 ~ 9, 1 ~ 1, 2 ~ 8, 3 ~ 2, 4 ~ 3, 5 ~ 6, 96:97 ~ 96, 98 ~ 99, 99 ~ 98),
      # language <- language_home or mother_tongue | language spoken at home; mother tongue where that is missing
      language = coalesce(in_range(language_home, 1, 99), in_range(mother_tongue, 1, 99)),
      # language_var <- language_home or mother_tongue | which source supplied language: 1 = spoken at home, 2 = mother tongue
      language_var = coalesce(recode_values(as.numeric(language_home), 1:99 ~ 1), recode_values(as.numeric(mother_tongue), 1:99 ~ 2))
    )
  },
