      occupation = recode_values(as.numeric(..d[["ces06_pes_sd3"]]), 12:13 ~ 1, 15:16 ~ 1, 111:112 ~ 1, 114 ~ 1, 121:123 ~ 1, 211 ~ 1, 213 ~ 1, 311:313 ~ 1, 411:412 ~ 1, 414 ~ 1, 512:513 ~ 1, 611 ~ 1, 621 ~ 1, 631:632 ~ 1, 641 ~ 1, 643 ~ 1, 651 ~ 1, 711:713 ~ 1, 721:722 ~ 1, 811 ~ 1, 911:912 ~ 1, 1111:1114 ~ 2, 1121:1122 ~ 2, 1211:1212 ~ 1, 1214:1215 ~ 1, 1221 ~ 3, 1223:1225 ~ 3, 1228 ~ 2, 1231:1234 ~ 3, 1236 ~ 3, 1241:1243 ~ 3, 1411 ~ 3, 1413:1414 ~ 3, 1422 ~ 3, 1431 ~ 3, 1433:1434 ~ 3, 1441:1442 ~ 3, 1452:1453 ~ 3, 1462:1463 ~ 3, 1471:1473 ~ 3, 1475 ~ 3, 2111:2114 ~ 2, 2121:2123 ~ 2, 2131:2134 ~ 2, 2141 ~ 2, 2145 ~ 2, 2147:2148 ~ 2, 2151 ~ 2, 2162:2163 ~ 2, 2211 ~ 4, 2225 ~ 4, 2231:2234 ~ 4, 2241:2244 ~ 4, 2251:2252 ~ 4, 2262 ~ 4, 2264 ~ 4, 2271 ~ 2, 2272 ~ 4, 3111:3114 ~ 2, 3121 ~ 2, 3131:3132 ~ 2, 3152 ~ 2, 3211 ~ 3, 3213:3215 ~ 3, 3233 ~ 2, 3234:3235 ~ 4, 3323 ~ 2, 3411 ~ 4, 3413:3414 ~ 4, 4112 ~ 2, 4121:4122 ~ 2, 4131 ~ 2, 4141:4143 ~ 2, 4152:4154 ~ 2, 4161:4165 ~ 2, 4168:4169 ~ 2, 4199 ~ 2, 4211:4213 ~ 3, 4214 ~ 4, 4215 ~ 2, 5111 ~ 2, 5121:5124 ~ 2, 5131 ~ 2, 5136 ~ 2, 5211 ~ 3, 5223 ~ 4, 5226:5227 ~ 4, 5231 ~ 2, 5241 ~ 3, 5242 ~ 4, 5254 ~ 4, 6211:6212 ~ 1, 6214:6216 ~ 4, 6221 ~ 3, 6231:6233 ~ 3, 6241 ~ 2, 6242 ~ 4, 6252 ~ 4, 6261:6262 ~ 4, 6271 ~ 4, 6411 ~ 3, 6421 ~ 3, 6431 ~ 3, 6433 ~ 3, 6435 ~ 3, 6441:6442 ~ 4, 6453 ~ 4, 6462 ~ 4, 6464 ~ 5, 6471:6472 ~ 4, 6474 ~ 4, 6482 ~ 4, 6611 ~ 4, 6622:6623 ~ 4, 6641:6642 ~ 4, 6651 ~ 4, 6661:6663 ~ 4, 6683 ~ 4, 7212:7216 ~ 4, 7219 ~ 4, 7221:7222 ~ 4, 7231:7232 ~ 4, 7241 ~ 4, 7245:7246 ~ 4, 7251:7252 ~ 4, 7265 ~ 4, 7271:7272 ~ 4, 7293:7295 ~ 4, 7311:7313 ~ 4, 7315 ~ 4, 7321:7322 ~ 4, 7335 ~ 4, 7341:7342 ~ 4, 7351:7352 ~ 4, 7381 ~ 4, 7411 ~ 4, 7413 ~ 4, 7421 ~ 4, 7441:7443 ~ 4, 7445 ~ 4, 7451:7452 ~ 4, 7611:7612 ~ 4, 7621:7622 ~ 4, 8211 ~ 1, 8241 ~ 4, 8251 ~ 6, 8254 ~ 6, 8256 ~ 4, 8262 ~ 6, 8421:8422 ~ 4, 8431:8432 ~ 6, 9223:9224 ~ 1, 9231 ~ 4, 9411 ~ 4, 9414 ~ 4, 9422:9424 ~ 4, 9431:9433 ~ 4, 9435:9436 ~ 4, 9471 ~ 4, 9482:9483 ~ 4, 9498 ~ 4, 9512 ~ 4, 9514:9515 ~ 4, 9517 ~ 4, 9613 ~ 4, 9616:9619 ~ 4),
      # province <- ces06_province | province of interview
      province = in_range(..d[["ces06_province"]], 10, 59),
      # region <- ces06_province | province of interview
      region = recode_values(as.numeric(..d[["ces06_province"]]), 10:13 ~ 1, 24 ~ 2, 35 ~ 3, 46:48 ~ 4, 59 ~ 5),
