      vote_choice = recode_values(as.numeric(..d[["ces06_pes_b4a"]]), 0 ~ 9, 1 ~ 1, 2 ~ 2, 3 ~ 3, 4 ~ 6, 5 ~ 10, 97 ~ 96, 98 ~ 99, 99 ~ 98),
